SELECT current_database(), current_user;
SELECT table_schema, table_name
FROM information_schema.tables
WHERE table_schema IN
 ('s1_core','s2_payments','s3_digital','stg','dw','audit')
ORDER BY table_schema, table_name;

SELECT * FROM s1_core.customer
ORDER BY customer_id LIMIT 10;
SELECT * FROM s2_payments.transaction
ORDER BY transaction_id LIMIT 10;
SELECT * FROM s3_digital.activity
ORDER BY activity_id LIMIT 10;

SELECT disposition, count(*) AS rows, sum(amount) AS aud
FROM stg.tx_decision
GROUP BY disposition ORDER BY disposition;
SELECT source_table, source_key, reason, amount_aud
FROM dw.rejected_record
ORDER BY source_table, source_key;

SELECT * FROM dw.v_r2_transaction_by_date_channel
ORDER BY full_date, channel_code;
SELECT * FROM dw.v_r2b_transaction_by_channel
ORDER BY channel_code;

SELECT * FROM dw.v_r3_channel_engagement
ORDER BY channel_code;
SELECT * FROM dw.v_r4_service_case_summary
ORDER BY status;

SELECT transaction_id, payment_customer_id, account_id,
       amount, status, source_transaction_ref
FROM s2_payments.transaction
WHERE transaction_id='T000001';

SELECT transaction_id, disposition, customer_key,
       account_key, amount, batch_id
FROM stg.tx_decision WHERE transaction_id='T000001';

SELECT transaction_id, customer_key, account_key,
       amount_aud, source_transaction_ref, batch_id
FROM dw.fact_transaction WHERE transaction_id='T000001';

SELECT transaction_id, disposition, source_transaction_ref
FROM stg.tx_decision
WHERE transaction_id IN ('T000100','T002001');
SELECT * FROM dw.rejected_record
WHERE source_key='T002001';

SELECT batch_id, status, started_at, finished_at, error
FROM audit.batch ORDER BY started_at DESC LIMIT 10;
SELECT * FROM audit.step_counts
ORDER BY batch_id DESC, step LIMIT 12;
